/* Explicit daily-life choices, factual relatives, and replaceable memory artwork. */
(function(root){
'use strict';
const now=()=>S.age*12+Math.floor((S.t||0)*12+1e-6),usd=n=>LifelineEconomy.toUSD(n);
const habits={walk:{name:'Гулять каждый вечер',hours:3.5,effects:'Здоровье до +3/год · Счастье до +2/год'},sport:{name:'Регулярная активность',hours:4,effects:'Здоровье до +3/год · Счастье до +1/год'},hobby:{name:'Заниматься хобби',hours:7,effects:'Развитие увлечения · Счастье до +2/год'},family:{name:'Ужины и время с близкими',hours:7,effects:'Отношения до +3/год · Счастье до +2/год'},learn:{name:'Учиться в свободное время',hours:7,effects:'Знания до +3/год'}};
function state(){return S.lifelineDetails||(S.lifelineDetails={at:now(),habits:{},album:[],seen:{},recovery:null,lastMoveOffer:null});}
function time(){const s=state(),working=isWorking(),studying=!!S.school,base=working?28:studying?32:49,children=homeOthers().kids.filter(k=>S.age-k.bornAt<6).length,care=Math.min(14,children*7),commute=working&&typeof commuteMin==='function'?Math.min(14,commuteMin()*5/60):0,course=S.flags.train||S.flags.nightUni||S.flags.nightGrad?6:0,available=Math.max(7,base-care-commute-course),focus=S.focus==='hobby'?7:S.focus==='learn'?7:S.focus==='people'?7:0,used=Object.keys(habits).reduce((n,k)=>n+(s.habits[k]&&!(k==='walk'&&noWalk())?habits[k].hours:0),0)+focus,ratio=used?Math.min(1,available/used):1;return {available:Math.round(available*10)/10,used,ratio,care,commute:Math.round(commute*10)/10,course,focus,overloaded:used>available};}
function setHabit(key,enabled){if(!habits[key]||S.age<6||S.phase!=='life')throw Error('Эта привычка пока недоступна');if(key==='walk'&&enabled&&noWalk())throw Error('Выберите доступную регулярную активность вместо ходьбы');state().habits[key]=!!enabled;}
function memory(kind,title,key,age=S.age){const s=state();if(s.seen[key])return;s.seen[key]=true;s.album.push({id:key,kind,title,age,country:text(C().ko),year:S.by+Math.floor(age),placeholder:true});const patterns={birth:/родил|рождение/i,wedding:/свадьб|пожен|вступ.*брак/i,home:/переех|приобрели.*дом|купили.*дом/i,graduation:/окончили|закончили|выпуск/i,retirement:/пенси/i};const row=(S.log||[]).slice().reverse().find(r=>r.a===Math.floor(age)&&!r.memoryId&&patterns[kind]?.test(r.text));if(row)row.memoryId=key;}
function grandRows(){return (S.fam.grand||[]).filter(g=>!g.gone).map((g,i)=>{const index=S.fam.grand.indexOf(g),parent=S.fam.kids.find(k=>(k.name?.g?callName(k.name):k.name?.full)===g.of&&k.sex===g.ofSex),age=Math.max(0,S.age+(S.t||0)-g.bornAt),name=text(g.name?.full||g.name||(g.sex==='M'?'Внук':'Внучка')+' · '+g.of);return {id:'grandchild-'+index,group:'grandchildren',name,role:g.sex==='M'?'Внук':'Внучка',alive:true,home:!!g.withMe,person:{name:{full:name},age,sex:g.sex},occupation:age<6?'Дошкольник':age<18?'Учится':'Занятость неизвестна',place:text(CBY[g.cur||parent?.cur||parent?.abroad||S.cur]?.ko||C().ko)};});}
function health(){const s=state(),conds=Object.entries(S.conds||{}).filter(([,v])=>v&&v.dx).map(([key,c])=>({name:text(ncdName(key)),status:c.treated?'Лечение продолжается':'Лечение не выбрано',cost:usd(rxCost(C(),key,S.age)),kind:'chronic'}));if(s.recovery&&now()<s.recovery.until)conds.unshift({name:s.recovery.name,status:'Восстановление · ещё '+(s.recovery.until-now())+' мес.',kind:'injury'});if(disOn())conds.push({name:text(disLabel0()),status:S.dis.aid?'Используются средства поддержки':'Доступные действия зависят от состояния',kind:'disability'});return {conditions:conds,disability:disOn()?{kind:S.dis.k,wheelchair:!!S.dis.wc,aid:!!S.dis.aid,label:text(disLabel0())}:null,injury:s.recovery&&now()<s.recovery.until?s.recovery:null,diet:S.flags.diet||'usual',insurance:S.flags.ins||'base',habits:Object.entries(habits).map(([id,h])=>({...h,id,on:!!s.habits[id],disabled:S.age<6||id==='walk'&&noWalk()&&!s.habits[id],reason:S.age<6?'Пока решения принимают взрослые':id==='walk'&&noWalk()?'Выберите доступную регулярную активность':''})),time:time()};}
function career(){const working=isWorking(),steps=working?ladder(S.job)||[]:[],rank=working?rankOf(S.job):0,training=LifelineSchedules.stage();return {working,title:text(rankTitle(S.job)||JOBS[S.job]?.n||S.job),formal:working?(S.formal?'Официальная работа':'Неофициальная работа'):'',income:usd(S.income||0),experience:S.jobY||0,knowledge:Math.round(S.st.sm),training:training.level,nextCourse:training.title,requirements:working&&steps[rank]?{tenure:rank>=2?12:rank?6:4,experience:typeof expIn==='function'?expIn(S.job).same:S.jobY,age:rank>=2?40:22,special:['soldier','police','prof','clergy','coach'].includes(S.job)}:null,steps:steps.map((x,i)=>({title:text(x.n),done:i<rank,current:i===rank})),note:'Повышение зависит от стажа, позиции в профессии, обучения и доступных предложений. Оно не гарантировано после одного курса.'};}
function observe(){const s=state(),month=now();if(S.phase!=='life'){s.at=month;return;}if(month>s.at){const count=Math.min(12,month-s.at),t=time(),h={...s.habits,walk:s.habits.walk&&!noWalk()},r=t.ratio;if(S.age>=6){eff({hl:count*r*((h.walk?.25:0)+(h.sport?.25:0)),h:count*r*((h.walk?1/6:0)+(h.sport?1/12:0)+(h.hobby?1/6:0)+(h.family?1/6:0)),so:count*r*(h.family?.25:0),sm:count*r*(h.learn?.25:0)});if(h.hobby&&S.hobbies.length){const a=S.hobbies[0];a.lv=Math.min(10,(a.lv||0)+count*r/24);}}if(t.overloaded&&month-(s.warnAt??-999)>=6){s.warnAt=month;log('Свободное время перегружено: запланировано '+t.used+' ч. из '+t.available+' ч. в неделю. На каждое занятие удаётся выделить около '+Math.round(t.ratio*100)+'% времени; хобби и семейные вечера тоже сокращаются.','note');}s.at=month;}
for(const row of S.log||[]){if(/То, чему вы начали учиться уже в зрелые годы/.test(row.text)){const hobby=S.hobbies?.[0];row.text=hobby?'Увлечение «'+text(hobbyName(hobby.id))+'» стало даваться увереннее. Текущий уровень: '+Math.floor(hobby.lv||0)+'.':'Занятия для себя стали даваться легче. Вы чувствуете больше уверенности.';row.kind='note';}}
if(!s.seen['self-birth']){memory('birth','Начало вашей жизни','self-birth',0);s.album.find(m=>m.id==='self-birth').country=text(CBY[S.born]?.ko||S.born);}
if(S.fam.marriages)memory('wedding','День свадьбы','wedding-'+S.fam.marriages,S.fam.marriedAt??S.age);
S.fam.kids.forEach((k,i)=>{if(!k.sk)memory('birth','Рождение: '+text(k.name?.g?callName(k.name):k.name?.full||'ребёнок'),'birth-'+i+'-'+k.bornAt,k.bornAt);});
if(S.edu>=3&&S.flags.justGrad)memory('graduation','Выпускной','graduation-'+S.edu+'-'+S.flags.justGrad);
if(S.retired)memory('retirement','Начало жизни на пенсии','retirement');
}
function illnessView(view){if(!view||!S.flags.ill?.id||!ILLS[S.flags.ill.id])return view;const f=S.flags.ill,price=f.cost*(1-(f.sh||0));view.body='Симптомы: '+text(ILLS[f.id].b)+'\n\nВозможная причина: '+text(illDx(f.id))+'. Диагноз уточняется при обращении.\nЛичная стоимость лечения: '+wonStr(price)+'. Доступно: '+wonStr(cashV())+'.';view.choices.forEach(c=>{c.sub=c.k==='hospital'?'Обследование и лечение · '+wonStr(price)+(price>cashV()?' · потребуется долг':''):'Меньше расходов сейчас · риск осложнений и более долгого восстановления';});return view;}
function adapt(){if(S.pending?.id==='illness')S.pending.view=illnessView(S.pending.view);}
function install(){const annual=endYear;endYear=function(...args){const ratio=time().ratio,levels=(S.hobbies||[]).map(h=>({h,lv:h.lv})),result=annual.apply(this,args);if(ratio<1)for(const old of levels)if(S.hobbies.includes(old.h)&&old.h.lv>old.lv)old.h.lv=old.lv+(old.h.lv-old.lv)*ratio;return result;};const oldIll=DEC.illness.build;DEC.illness.build=function(...args){return illnessView(oldIll.apply(this,args));};const illApply=DEC.illness.apply;DEC.illness.apply=function(key,...args){const f={...S.flags.ill},result=illApply.call(this,key,...args);if(S.phase==='life'&&['frac','disc'].includes(f.id))state().recovery={name:text(illDx(f.id)),kind:f.id==='frac'?'cast':'back',until:now()+(key==='hospital'?3:6)};return result;};
const move=SHOP.find(x=>x.id==='moveout'),oldOK=move.ok;const moveRun=move.run;move.opts=()=>[['room'],['flat']];move.optN=k=>k==='room'?'Снять комнату':'Снять отдельное жильё';move.cost=k=>incomeAt(C(),.5)*(k==='room'?.08:.15);move.run=function(k){state().rentedType=k==='room'?'room':'flat';return moveRun()+ (k==='room'?' Вы сняли комнату с общими помещениями.':' Вы сняли отдельное жильё.');};move.ok=()=>S.age>=18&&withParents()&&!S.owns.house;move.lock=()=>oldOK()?null:S.school&&studyAway()?'Вы уже живёте по месту учёбы':S.job==='prison'?'Недоступно во время заключения':S.refugee||S.nomad?'Сначала нужно постоянное место жительства':S.serveLeft>0?'Сначала завершите службу':!parentAlive()?'Это жильё уже не считается родительским':S.age>=60?'Выберите другой вариант переезда в разделе «Дом»':'Сейчас самостоятельный съезд недоступен';
const items=shopItems;shopItems=function(...args){const rows=items.apply(this,args);for(const row of rows){if(row.id==='kidmoney'&&row.opts){const hasGrand=kmGrand().length>0,hasGreat=kmGG()>0;row.opts=row.opts.filter(o=>o.id.endsWith('@kids')||hasGrand||hasGreat);}if(row.id==='moveout'){if(!row.avail&&!row.why)row.why='Сейчас съезд недоступен';for(const o of row.opts||[])if(!o.avail&&!o.why)o.why=row.why||'Нужны деньги на залог и обустройство: '+wonStr(o.price);}}return rows;};
for(const id of ['movenear','city','move'])if(DEC[id]?.build){const build=DEC[id].build;DEC[id].build=function(...args){const s=state(),v=build.apply(this,args);if(!v)return v;if(s.lastMoveOffer!=null&&now()-s.lastMoveOffer<36)return null;s.lastMoveOffer=now();return v;};}
}
function summary(){return {health:health(),career:career(),album:state().album,hobbies:(S.hobbies||[]).map(h=>({id:h.id,name:text(hobbyName(h.id)),level:Math.floor(h.lv||0)})),time:time()};}
root.LifelineDetails={state,time,setHabit,memory,grandRows,health,career,observe,install,adapt,summary};
})(self);
